1	/****************************************************************************
2	 * apps/examples/xiaozhi_voice/xiaozhi_audio.c
3	 *
4	 * Audio capture (mic -> Opus 16kHz) and playback (Opus 24kHz -> speaker)
5	 * using direct Opus API for encoding and Vela media framework for decoding.
6	 * The SMF framework's Opus encoder adds non-standard headers that break
7	 * compatibility with the xiaozhi server, so we use the Opus API directly
8	 * for encoding. For playback, the SMF decoder works correctly.
9	 *
10	 * SPDX-License-Identifier: Apache-2.0
11	 ****************************************************************************/
12	
13	#include <nuttx/config.h>
14	
15	#include <stdio.h>
16	#include <string.h>
17	#include <errno.h>
18	#include <pthread.h>
19	
20	#include <opus.h>
21	
22	#include <media_recorder.h>
23	#include <media_player.h>
24	#include <media_defs.h>
25	
26	#include "xiaozhi_audio.h"
27	
28	/****************************************************************************
29	 * Pre-processor Definitions
30	 ****************************************************************************/
31	
32	/* Uplink: 16kHz mono Opus encoding parameters (direct API). */
33	#define XZ_OPUS_SAMPLE_RATE  16000
34	#define XZ_OPUS_CHANNELS     1
35	#define XZ_OPUS_BITRATE      64000   /* 提高比特率到64kbps，保留更多音频细节 */
36	#define XZ_OPUS_FRAME_MS     40      /* 缩小帧大小到40ms，提高时域分辨率 */
37	#define XZ_OPUS_APPLICATION  OPUS_APPLICATION_VOIP
38	#define XZ_OPUS_FRAME_SIZE   (XZ_OPUS_SAMPLE_RATE * XZ_OPUS_FRAME_MS / 1000)  /* 640 samples */
39	
40	/* PCM capture options: raw 16-bit mono 16kHz from mic via SMF. */
41	#define XZ_PCM_RECORDER_OPTIONS \
42	  "fmt=[rate=#16000,ch=#1,bits=#16,width=#2],enc=[keys=pcm,imin=#1280]"  /* 40ms frame: 1280 bytes */
43	
44	/* Downlink: 24kHz mono Opus (xiaozhi server TTS sample rate, SMF native format). */
45	#define XZ_PLAYER_OPTIONS \
46	  "oMediaScript=[codec=opus,rate=#24000,ch=#1,bits=#16]"
47	
48	/* Max single Opus frame we expect / send. */
49	#define XZ_OPUS_FRAME_MAX 1024  /* 增加最大帧大小以适应更高的比特率 */
50	
51	/* PCM read buffer size: one 40ms frame at 16kHz mono 16-bit = 1280 bytes. */
52	#define XZ_PCM_BUF_SIZE (XZ_OPUS_FRAME_SIZE * XZ_OPUS_CHANNELS * sizeof(opus_int16))
53	
54	/****************************************************************************
55	 * Private Data
56	 ****************************************************************************/
57	
58	struct xiaozhi_audio_s
59	{
60	  /* Recording path (mic -> PCM -> Opus encode -> send). */
61	  void             *recorder;       /* SMF recorder handle (void*). */
62	  OpusEncoder      *opus_encoder;   /* Direct Opus encoder. */
63	  opus_int16        pcm_buf[XZ_OPUS_FRAME_SIZE * XZ_OPUS_CHANNELS];
64	  uint8_t           opus_buf[XZ_OPUS_FRAME_MAX];
65	  pthread_mutex_t   enc_mutex;
66	
67	  /* Playback path (recv Opus -> SMF decode -> speaker). */
68	  void             *player;         /* SMF player handle (void*). */
69	};
70	
71	static struct xiaozhi_audio_s g_audio;
72	
73	/****************************************************************************
74	 * Public Functions
75	 ****************************************************************************/
76	
77	struct xiaozhi_audio_s *xiaozhi_audio_init(void)
78	{
79	  struct xiaozhi_audio_s *a = &g_audio;
80	  int err;
81	
82	  memset(a, 0, sizeof(*a));
83	  pthread_mutex_init(&a->enc_mutex, NULL);
84	
85	  /* Create Opus encoder: 16kHz mono, VOIP application, 60ms frames. */
86	  a->opus_encoder = opus_encoder_create(XZ_OPUS_SAMPLE_RATE,
87	                                        XZ_OPUS_CHANNELS,
88	                                        XZ_OPUS_APPLICATION,
89	                                        &err);
90	  if (a->opus_encoder == NULL)
91	    {
92	      printf("[xiaozhi] opus_encoder_create failed: %s\n", opus_strerror(err));
93	      return NULL;
94	    }
95	
96	  /* Configure encoder for xiaozhi compatibility. */
97	  opus_encoder_ctl(a->opus_encoder, OPUS_SET_BITRATE(XZ_OPUS_BITRATE));
98	  opus_encoder_ctl(a->opus_encoder, OPUS_SET_COMPLEXITY(8));  /* 提高复杂度到8，获得更好的编码质量 */
99	  opus_encoder_ctl(a->opus_encoder, OPUS_SET_SIGNAL(OPUS_SIGNAL_VOICE));
100	  opus_encoder_ctl(a->opus_encoder, OPUS_SET_LSB_DEPTH(16));
101	  /* 启用语音优化和丢包隐藏 */
102	  opus_encoder_ctl(a->opus_encoder, OPUS_SET_INBAND_FEC(1));  /* 启用带内FEC，提高抗丢包能力 */
103	  opus_encoder_ctl(a->opus_encoder, OPUS_SET_DTX(1));  /* 启用DTX，静音时不发送数据 */
104	  opus_encoder_ctl(a->opus_encoder, OPUS_SET_PACKET_LOSS_PERC(5));  /* 假设5%丢包率，启用丢包隐藏 */
105	
106	  printf("[xiaozhi] opus encoder created: %dHz %dch %dbps %dms frame (optimized)\n",
107	         XZ_OPUS_SAMPLE_RATE, XZ_OPUS_CHANNELS, XZ_OPUS_BITRATE,
108	         XZ_OPUS_FRAME_MS);
109	
110	  return a;
111	}
112	
113	int xiaozhi_audio_start_capture(struct xiaozhi_audio_s *a)
114	{
115	  int ret;
116	
117	  if (a == NULL)
118	    {
119	      return -EINVAL;
120	    }
121	
122	  /* Tear down any previous recorder. */
123	  if (a->recorder != NULL)
124	    {
125	      media_recorder_stop(a->recorder);
126	      media_recorder_close(a->recorder);
127	      a->recorder = NULL;
128	    }
129	
130	  a->recorder = media_recorder_open(MEDIA_SOURCE_MIC);
131	  if (a->recorder == NULL)
132	    {
133	      printf("[xiaozhi] media_recorder_open failed\n");
134	      return -EIO;
135	    }
136	
137	  /* Buffer mode: capture raw PCM. We encode to Opus ourselves. */
138	  ret = media_recorder_prepare(a->recorder, NULL, XZ_PCM_RECORDER_OPTIONS);
139	  if (ret < 0)
140	    {
141	      printf("[xiaozhi] recorder prepare failed: %d\n", ret);
142	      media_recorder_close(a->recorder);
143	      a->recorder = NULL;
144	      return ret;
145	    }
146	
147	  ret = media_recorder_start(a->recorder);
148	  if (ret < 0)
149	    {
150	      printf("[xiaozhi] recorder start failed: %d\n", ret);
151	      media_recorder_close(a->recorder);
152	      a->recorder = NULL;
153	      return ret;
154	    }
155	
156	  printf("[xiaozhi] capture started (16k PCM -> opus encode, 40ms frame, 64kbps)\n");
157	  return 0;
158	}
159	
160	ssize_t xiaozhi_audio_read_opus(struct xiaozhi_audio_s *a,
161	                                uint8_t *buf, size_t maxlen)
162	{
163	  ssize_t total = 0;
164	  ssize_t n;
165	  int encoded_bytes;
166	  int frame_samples;
167	
168	  if (a == NULL || a->recorder == NULL || buf == NULL)
169	    {
170	      return -EINVAL;
171	    }
172	
173	  /* Read exactly one 40ms PCM frame from the SMF recorder.
174	   * At 16kHz mono 16-bit, one 40ms frame = 640 samples = 1280 bytes.
175	   * media_recorder_read_data may return partial reads, so loop until
176	   * we have the full frame.
177	   */
178	  while (total < XZ_PCM_BUF_SIZE)
179	    {
180	      n = media_recorder_read_data(a->recorder,
181	                                   (uint8_t *)a->pcm_buf + total,
182	                                   XZ_PCM_BUF_SIZE - total);
183	      if (n <= 0)
184	        {
185	          printf("[xiaozhi] pcm read returned: %zd (got %zd/%d)\n",
186	                 n, total, XZ_PCM_BUF_SIZE);
187	          return n > 0 ? -EIO : n;
188	        }
189	
190	      total += n;
191	    }
192	
193	  /* Encode PCM to Opus. opus_encode takes sample count, not byte count.
194	   * frame_samples = total_bytes / (channels * bytes_per_sample)
195	   *               = 1280 / (1 * 2) = 640 samples for 40ms at 16kHz.
196	   */
197	  frame_samples = total / (XZ_OPUS_CHANNELS * sizeof(opus_int16));
198	  encoded_bytes = opus_encode(a->opus_encoder,
199	                              a->pcm_buf,
200	                              frame_samples,
201	                              a->opus_buf,
202	                              XZ_OPUS_FRAME_MAX);
203	  if (encoded_bytes < 0)
204	    {
205	      printf("[xiaozhi] opus_encode error: %s (samples=%d)\n",
206	             opus_strerror(encoded_bytes), frame_samples);
207	      return -EIO;
208	    }
209	
210	  /* Copy encoded frame to caller's buffer. */
211	  if ((size_t)encoded_bytes > maxlen)
212	    {
213	      printf("[xiaozhi] opus frame too large: %d > %zu\n", encoded_bytes, maxlen);
214	      return -ENOMEM;
215	    }
216	
217	  memcpy(buf, a->opus_buf, encoded_bytes);
218	
219	  return (ssize_t)encoded_bytes;
220	}
221	
222	int xiaozhi_audio_stop_capture(struct xiaozhi_audio_s *a)
223	{
224	  if (a == NULL || a->recorder == NULL)
225	    {
226	      return -EINVAL;
227	    }
228	
229	  media_recorder_stop(a->recorder);
230	  media_recorder_close(a->recorder);
231	  a->recorder = NULL;
232	  printf("[xiaozhi] capture stopped\n");
233	  return 0;
234	}
235	
236	int xiaozhi_audio_start_playback(struct xiaozhi_audio_s *a)
237	{
238	  int ret;
239	
240	  if (a == NULL)
241	    {
242	      return -EINVAL;
243	    }
244	
245	  if (a->player != NULL)
246	    {
247	      media_player_stop(a->player);
248	      media_player_close(a->player, 0);
249	      a->player = NULL;
250	    }
251	
252	  a->player = media_player_open(MEDIA_STREAM_MUSIC);
253	  if (a->player == NULL)
254	    {
255	      printf("[xiaozhi] media_player_open failed\n");
256	      return -EIO;
257	    }
258	
259	  /* Buffer mode: url = NULL. The framework decodes Opus; we feed encoded
260	   * frames via media_player_write_data().
261	   */
262	  ret = media_player_prepare(a->player, NULL, XZ_PLAYER_OPTIONS);
263	  if (ret < 0)
264	    {
265	      printf("[xiaozhi] player prepare failed: %d\n", ret);
266	      media_player_close(a->player, 0);
267	      a->player = NULL;
268	      return ret;
269	    }
270	
271	  ret = media_player_start(a->player);
272	  if (ret < 0)
273	    {
274	      printf("[xiaozhi] player start failed: %d\n", ret);
275	      media_player_close(a->player, 0);
276	      a->player = NULL;
277	      return ret;
278	    }
279	
280	  printf("[xiaozhi] playback started (24k opus)\n");
281	  return 0;
282	}
283	
284	int xiaozhi_audio_write_opus(struct xiaozhi_audio_s *a,
285	                             const uint8_t *data, size_t len)
286	{
287	  ssize_t ret;
288	
289	  if (a == NULL || a->player == NULL || data == NULL)
290	    {
291	      return -EINVAL;
292	    }
293	
294	  ret = media_player_write_data(a->player, data, len);
295	  if (ret < 0)
296	    {
297	      printf("[xiaozhi] player write_data failed: %zd\n", ret);
298	      return ret;
299	    }
300	
301	  return 0;
302	}
303	
304	int xiaozhi_audio_stop_playback(struct xiaozhi_audio_s *a)
305	{
306	  if (a == NULL || a->player == NULL)
307	    {
308	      return -EINVAL;
309	    }
310	
311	  media_player_stop(a->player);
312	  media_player_close(a->player, 0);
313	  a->player = NULL;
314	  printf("[xiaozhi] playback stopped\n");
315	  return 0;
316	}
317	
318	void xiaozhi_audio_deinit(struct xiaozhi_audio_s *a)
319	{
320	  if (a == NULL)
321	    {
322	      return;
323	    }
324	
325	  if (a->recorder != NULL)
326	    {
327	      media_recorder_stop(a->recorder);
328	      media_recorder_close(a->recorder);
329	      a->recorder = NULL;
330	    }
331	
332	  if (a->player != NULL)
333	    {
334	      media_player_stop(a->player);
335	      media_player_close(a->player, 0);
336	      a->player = NULL;
337	    }
338	
339	  if (a->opus_encoder != NULL)
340	    {
341	      opus_encoder_destroy(a->opus_encoder);
342	      a->opus_encoder = NULL;
343	    }
344	
345	  pthread_mutex_destroy(&a->enc_mutex);
346	}
