127	/* Tool: self.stopwatch.start — open stopwatch and start timing. */
128	
129	static cJSON *mcp_tool_stopwatch_start(const cJSON *args)
130	{
131	  printf("[mcp] tool: stopwatch.start\n");
132	  pthread_mutex_lock(&s_ui_mutex);
133	  /* Navigate to app page first, then start stopwatch */
134	  nav_enter_app();
135	  stopwatch_start();
136	  /* stopwatch_start() already creates UI and calls start_stopwatch(),
137	   * so timing begins immediately. */
138	  pthread_mutex_unlock(&s_ui_mutex);
139	  return cJSON_CreateString("ok");
140	}
