188	static void alarm_add_async_cb(void *arg)
189	{
190	  struct alarm_add_args *a = (struct alarm_add_args *)arg;
191	  /* Ensure clock view is initialized before adding alarm.
192	   * clock_main_start() is safe to call multiple times —
193	   * alarm_model_init() has a static initialized guard. */
194	  nav_enter_app();
195	  clock_main_start();
