200	/* Tool: self.clock.open — open the clock/alarm app. */

200	/* Tool: self.clock.open — open the clock/alarm app. */
201	
202	static cJSON *mcp_tool_clock_open(const cJSON *args)
203	{
204	  printf("[mcp] tool: clock.open\n");
205	  /* Defer UI creation to the main LVGL thread to avoid racing
206	   * with lv_timer_handler / display refresh. */
207	  lv_async_call(clock_open_async_cb, NULL);
208	  return cJSON_CreateString("ok");
209	}
