211	/* Tool: self.alarm.add — add an alarm.
212	 * Arguments: {"hour": "08", "minute": "30"}
213	 */
214	
215	static cJSON *mcp_tool_alarm_add(const cJSON *args)
216	{
217	  const char *hour = "8";
218	  const char *minute = "0";
219	
220	  if (args != NULL)
221	    {
222	      cJSON *h = cJSON_GetObjectItem(args, "hour");
223	      cJSON *m = cJSON_GetObjectItem(args, "minute");
224	      if (cJSON_IsString(h))
225	        {
226	          hour = h->valuestring;
227	        }
228	
229	      if (cJSON_IsString(m))
230	        {
231	          minute = m->valuestring;
232	        }
233	    }
234	
235	  printf("[mcp] tool: alarm.add %s:%s\n", hour, minute);
236	  /* Defer UI creation to the main LVGL thread. */
237	  struct alarm_add_args *a = malloc(sizeof(*a));
238	  if (a)
239	    {
240	      snprintf(a->hour, sizeof(a->hour), "%s", hour);
241	      snprintf(a->minute, sizeof(a->minute), "%s", minute);
242	      lv_async_call(alarm_add_async_cb, a);
243	    }
244	
245	  char resp[64];
246	  snprintf(resp, sizeof(resp), "alarm set to %s:%s", hour, minute);
247	  return cJSON_CreateString(resp);
248	}
