282	/****************************************************************************
283	 * Listening动画函数
284	 ****************************************************************************/
285	
286	/* 生成目标高度 */
287	static void wave_gen_targets(void)
288	{
289	    for (int i = 0; i < BAR_COUNT; i++) {
290	        float t = (float)i / BAR_COUNT;
291	        float env = expf(-5.0f * (t - 0.5f) * (t - 0.5f));
292	        float r = fabsf(sinf(t * 13.7f + s_tick * 0.9f)) * 0.4f
293	                + fabsf(cosf(t * 23.1f - s_tick * 0.6f)) * 0.35f
294	                + fabsf(sinf(t * 7.3f + s_tick * 1.4f)) * 0.25f;
295	        s_bar_tgt[i] = r * env;
296	    }
297	}
298	
299	/* 定时器回调 */
300	static void wave_tick_cb(lv_timer_t *t)
301	{
302	    (void)t;
303	
304	    pthread_mutex_lock(&s_ui_mutex);
305	
306	    s_tick += 0.15f;
307	
308	    /* 每次都生成新的目标高度，让动画持续变化 */
309	    wave_gen_targets();
310	
311	    /* 更新每个柱子的高度和位置 */
312	    for (int i = 0; i < BAR_COUNT; i++) {
313	        float speed = 0.1f + (float)i / BAR_COUNT * 0.1f;  /* 加快响应速度 */
314	        s_bar_h[i] += (s_bar_tgt[i] - s_bar_h[i]) * speed;
315	
316	        /* 计算高度（像素） */
317	        int h = (int)(s_bar_h[i] * BAR_MAX_HEIGHT);
318	        if (h < 4) h = 4;
319	
320	        /* 更新柱子对象的高度和位置（保持底部对齐） */
321	        if (s_bars[i] != NULL) {
322	            lv_obj_set_height(s_bars[i], h);
323	            /* 底部对齐：y坐标 = 容器高度 - 柱子高度 */
324	            lv_obj_set_y(s_bars[i], BAR_MAX_HEIGHT + 10 - h);
325	        }
326	    }
327	
328	    pthread_mutex_unlock(&s_ui_mutex);
329	}
330	
331	/* 启动Listening动画 */
332	void wave_anim_start(lv_obj_t *parent)
333	{
334	    /* 如果已经创建，先停止 */
335	    wave_anim_stop();
336	
337	    memset(s_bar_h, 0, sizeof(s_bar_h));
338	    memset(s_bar_tgt, 0, sizeof(s_bar_tgt));
339	    s_tick = 0;
340	
341	    /* 创建柱子容器 */
342	    s_bar_container = lv_obj_create(parent);
343	    lv_obj_set_size(s_bar_container, 200, BAR_MAX_HEIGHT + 10);  /* 容器高度 */
344	    lv_obj_align(s_bar_container, LV_ALIGN_TOP_MID, 0, 55);     /* 在status_label(60)上面一点 */
345	    lv_obj_set_style_bg_opa(s_bar_container, LV_OPA_TRANSP, 0);
346	    lv_obj_set_style_border_width(s_bar_container, 0, 0);
347	    lv_obj_set_style_pad_all(s_bar_container, 0, 0);
348	    lv_obj_set_style_pad_top(s_bar_container, 0, 0);
349	    lv_obj_set_style_pad_bottom(s_bar_container, 0, 0);
350	    lv_obj_set_style_pad_left(s_bar_container, 0, 0);
351	    lv_obj_set_style_pad_right(s_bar_container, 0, 0);
352	    lv_obj_clear_flag(s_bar_container, LV_OBJ_FLAG_SCROLLABLE);
353	    lv_obj_clear_flag(s_bar_container, LV_OBJ_FLAG_HIDDEN);
354	
355	    /* 计算起始位置 */
356	    int total_width = BAR_COUNT * BAR_WIDTH + (BAR_COUNT - 1) * BAR_GAP;
357	    int x_start = (200 - total_width) / 2;
358	
359	    /* 创建7个柱子，底部对齐在容器底部 */
360	    for (int i = 0; i < BAR_COUNT; i++) {
361	        s_bars[i] = lv_obj_create(s_bar_container);
362	        lv_obj_set_size(s_bars[i], BAR_WIDTH, 4);  /* 初始高度4像素 */
363	        /* 柱子底部对齐：y坐标 = 容器高度 - 初始高度 */
364	        lv_obj_set_pos(s_bars[i], x_start + i * (BAR_WIDTH + BAR_GAP), BAR_MAX_HEIGHT + 10 - 4);
365	        lv_obj_set_style_bg_color(s_bars[i], lv_color_hex(BAR_COLOR), 0);
366	        lv_obj_set_style_bg_opa(s_bars[i], LV_OPA_COVER, 0);
367	        lv_obj_set_style_radius(s_bars[i], BAR_WIDTH / 2, 0);  /* 圆角 */
368	        lv_obj_set_style_border_width(s_bars[i], 0, 0);
369	        lv_obj_clear_flag(s_bars[i], LV_OBJ_FLAG_HIDDEN);
370	    }
371	
372	    /* 创建"我正在听..." label */
373	    s_listen_label = lv_label_create(parent);
374	    lv_label_set_text(s_listen_label, "我正在听...");
375	    lv_obj_set_style_text_font(s_listen_label, font_manager_get_font(FONT_LARGE), 0);
376	    lv_obj_set_style_text_color(s_listen_label, lv_color_hex(0xFF6900), 0);
377	    lv_obj_align(s_listen_label, LV_ALIGN_TOP_MID, 0, 170);  /* 在动画下方 */
378	
379	    wave_gen_targets();
380	    s_timer = lv_timer_create(wave_tick_cb, ANIM_MS, NULL);
381	
382	    printf("[xiaozhi] wave_anim_start: created %d bars\n", BAR_COUNT);
383	}
