386	void wave_anim_stop(void)
387	{
388	    if (s_timer) { lv_timer_del(s_timer); s_timer = NULL; }
389	
390	    for (int i = 0; i < BAR_COUNT; i++) {
391	        if (s_bars[i]) { lv_obj_del(s_bars[i]); s_bars[i] = NULL; }
392	    }
393	
394	    if (s_bar_container) { lv_obj_del(s_bar_container); s_bar_container = NULL; }
395	    if (s_listen_label) { lv_obj_del(s_listen_label); s_listen_label = NULL; }
