402	/* 定时器回调：更新圆点大小 */
403	static void think_tick_cb(lv_timer_t *t)
404	{
405	    (void)t;
406	
407	    pthread_mutex_lock(&s_ui_mutex);
408	
409	    s_think_tick++;
410	
411	    for (int i = 0; i < DOT_COUNT; i++) {
412	        float phase = (float)(s_think_tick - i * 2) / 4.0f;  /* 调整相位 */
413	        float tri = 1.0f - fabsf(fmodf(phase, 2.0f) - 1.0f);
414	        int size = (int)(DOT_SIZE * (0.4f + tri * 0.6f));
415	
416	        if (s_dots[i] != NULL) {
417	            lv_obj_set_size(s_dots[i], size, size);
418	            lv_obj_set_style_radius(s_dots[i], size / 2, 0);
419	        }
420	    }
421	
422	    pthread_mutex_unlock(&s_ui_mutex);
423	}
