596	/* Sanitize UTF-8 text: replace fullwidth CJK punctuation with ASCII
597	 * equivalents so the limited CJK font (basic ideographs only) can render
598	 * all visible characters without falling back to [][].
599	 */
600	static void sanitize_text(char *dst, size_t dstsize, const char *src)
601	{
602	  size_t di = 0;
603	  const unsigned char *s = (const unsigned char *)src;
604	
605	  while (*s && di < dstsize - 1)
606	    {
607	      /* 3-byte UTF-8: U+0800 .. U+FFFF */
608	      if (s[0] >= 0xe0 && s[1] >= 0x80 && s[1] < 0xc0 &&
609	          s[2] >= 0x80 && s[2] < 0xc0)
610	        {
611	          unsigned int cp = ((unsigned int)(s[0] & 0x0f) << 12) |
612	                            ((unsigned int)(s[1] & 0x3f) << 6) |
613	                            ((unsigned int)(s[2] & 0x3f));
614	          const char *r = NULL;
615	
616	          switch (cp)
617	            {
618	              case 0xff0c: r = ",";  break;  /* ， */
619	              case 0x3002: r = ".";  break;  /* 。 */
620	              case 0xff01: r = "!";  break;  /* ！ */
621	              case 0xff1f: r = "?";  break;  /* ？ */
622	              case 0xff1a: r = ":";  break;  /* ： */
623	              case 0xff1b: r = ";";  break;  /* ； */
624	              case 0x3001: r = ",";  break;  /* 、 */
625	              case 0x201c: r = "\""; break;  /* " */
626	              case 0x201d: r = "\""; break;  /* " */
627	              case 0x2018: r = "'";  break;  /* ' */
628	              case 0x2019: r = "'";  break;  /* ' */
629	              case 0xff08: r = "(";  break;  /* （ */
630	              case 0xff09: r = ")";  break;  /* ） */
631	              case 0x300a: r = "<<"; break;  /* 《 */
632	              case 0x300b: r = ">>"; break;  /* 》 */
633	              case 0x2026: r = "..."; break; /* … */
634	              case 0x2014: r = "--"; break;  /* — */
635	              default:
636	                {
637	                  /* Keep the original character if it's in CJK range */
638	                  if (cp >= 0x4e00 && cp <= 0x9fa5)
639	                    {
640	                      dst[di++] = s[0];
641	                      dst[di++] = s[1];
642	                      dst[di++] = s[2];
643	                    }
644	                  else
645	                    {
646	                      /* Unknown char: skip */
647	                    }
648	                  s += 3;
649	                  continue;
650	                }
651	            }
652	
653	          /* Write replacement string */
654	          while (*r && di < dstsize - 1)
655	            {
656	              dst[di++] = *r++;
657	            }
658	
659	          s += 3;
660	        }
661	      /* 2-byte UTF-8: U+0080 .. U+07FF (skip, not CJK) */
662	      else if (s[0] >= 0xc0 && s[0] < 0xe0 && s[1] >= 0x80)
663	        {
664	          s += 2;
665	        }
666	      /* ASCII */
667	      else if (s[0] < 0x80)
668	        {
669	          dst[di++] = *s++;
670	        }
671	      else
672	        {
673	          /* Invalid UTF-8 byte, skip */
674	          s++;
675	        }
676	    }
677	
678	  dst[di] = '\0';
679	}
