696	/* Uplink worker: capture Opus frames and send as binary frames for the
697	 * given number of seconds.
698	 */
699	static void *uplink_worker(void *arg)
700	{
701	  struct uplink_ctx_s *uc = arg;
702	  struct xiaozhi_app_s *app = uc->app;
703	  uint8_t frame[XZ_OPUS_MAX];
704	  int frames = 0;
705	  int target_frames = (uc->seconds * 1000) / 60;   /* 60ms per frame */
706	
707	  printf("[xiaozhi] uplink: capturing %d frames (%ds)\n",
708	         target_frames, uc->seconds);
709	
710	  
711	  printf("[xiaozhi] app->ws_connected %d\n", app->ws_connected);
712	
713	  while (frames < target_frames && app->ws_connected)
714	    {
715	      printf("[xiaozhi] in while show, frames=%d, target=%d, connected=%d\n",
716	             frames, target_frames, app->ws_connected);
717	      ssize_t n = xiaozhi_audio_read_opus(app->audio, frame, sizeof(frame));
718	      printf("[xiaozhi] read_opus returned: %zd\n", n);
719	      if (n < 0)
720	        {
721	          printf("[xiaozhi] uplink read err: %zd\n", n);
722	          break;
723	        }
724	
725	      if (n > 0)
726	        {
727	          /* Debug: hex dump first Opus frames for format verification. */
728	          if (frames < 3)
729	            {
730	              printf("[xiaozhi] opus frame[%d] len=%zd\n", frames, n);
731	              for (ssize_t i = 0; i < n && i < 32; i++)
732	                {
733	                  printf("%02x ", frame[i]);
734	                }
735	              printf("\n");
736	            }
737	
738	          int ret = xiaozhi_ws_send_binary(&app->ws, frame, n);
739	          if (ret != 0)
740	            {
741	              printf("[xiaozhi] uplink send err: %d\n", ret);
742	              break;
743	            }
744	
745	          frames++;
746	        }
747	    }
748	
749	  printf("[xiaozhi] uplink: sent %d/%d frames\n", frames, target_frames);
750	  return NULL;
751	}
