753	/* Receive worker: parse server messages and feed TTS audio to the player.
754	 * Runs until ws is closed or a stop condition.
755	 */
756	static void recv_loop(struct xiaozhi_app_s *app, int max_ms,
757	                      bool stop_on_hello)
758	{
759	  int waited = 0;
760	
761	  while (app->ws_connected && waited < max_ms && !app->mcp_done)
762	    {
763	      const uint8_t *payload;
764	      size_t plen;
765	      bool is_binary;
766	      int ret;
767	
768	      ret = xiaozhi_ws_recv(&app->ws, &payload, &plen, &is_binary);
769	      if (ret != 0)
770	        {
771	          app->ws_connected = false;
772	          break;
773	        }
774	
775	      if (is_binary)
776	        {
777	          printf("[xiaozhi] <<< binary frame: %zu bytes\n", plen);
778	          /* Server TTS Opus frame -> feed to player. */
779	          if (app->tts_playing)
780	            {
781	              xiaozhi_audio_write_opus(app->audio, payload, plen);
782	            }
783	
784	          waited += 60;
785	          continue;
786	        }
787	
788	      /* Text frame: parse JSON. */
789	      {
790	        char *json = malloc(plen + 1);
791	        if (json == NULL)
792	          {
793	            continue;
794	          }
795	
796	        memcpy(json, payload, plen);
797	        json[plen] = '\0';
798	
799	        cJSON *root = cJSON_Parse(json);

800	        if (root != NULL)
801	          {
802	            /* Print all received text messages for debugging. */
803	            printf("[xiaozhi] <<< recv: %s\n", json);
804	
805	            cJSON *type = cJSON_GetObjectItem(root, "type");
806	            const char *tstr = cJSON_IsString(type) ?
807	              type->valuestring : "";
808	
809	            if (strcmp(tstr, "stt") == 0)
810	              {
811	                cJSON *text = cJSON_GetObjectItem(root, "text");
812	                const char *s = text ? text->valuestring : "?";
813	                printf("[xiaozhi] <<< STT: \"%s\"\n", s);
814	                app->got_stt = true;
815	                sanitize_text(app->stt_text, sizeof(app->stt_text), s);
816	              }
817	            else if (strcmp(tstr, "llm") == 0)
818	              {
819	                cJSON *text = cJSON_GetObjectItem(root, "text");
820	                printf("[xiaozhi] <<< LLM: \"%s\"\n",
821	                       text ? text->valuestring : "?");
822	              }
823	            else if (strcmp(tstr, "tts") == 0)
824	              {
825	                cJSON *state = cJSON_GetObjectItem(root, "state");
826	                const char *sstr = cJSON_IsString(state) ?
827	                  state->valuestring : "";
828	
829	                if (strcmp(sstr, "start") == 0)
830	                  {
831	                    pthread_mutex_lock(&s_ui_mutex);
832	                    app->tts_playing = true;
833	                    app->state = XZ_STATE_PLAYING;
834	                    pthread_mutex_unlock(&s_ui_mutex);
835	                    xiaozhi_audio_start_playback(app->audio);
836	                    printf("[xiaozhi] <<< TTS start\n");
837	                  }
838	                else if (strcmp(sstr, "stop") == 0)
839	                  {
840	                    app->tts_playing = false;
841	                    printf("[xiaozhi] <<< TTS stop\n");
842	                    xiaozhi_audio_stop_playback(app->audio);
843	                    cJSON_Delete(root);
844	                    free(json);
845	                    break;   /* end of this turn */
846	                  }
847	                else if (strcmp(sstr, "sentence_start") == 0)
848	                  {
849	                    cJSON *text = cJSON_GetObjectItem(root, "text");
850	                    const char *s = text ? text->valuestring : "?";
851	                    printf("[xiaozhi] <<< TTS: \"%s\"\n", s);
852	                    app->tts_sentences++;
853	                    sanitize_text(app->tts_text, sizeof(app->tts_text), s);
854	                  }
855	              }
856	            else if (strcmp(tstr, "goodbye") == 0)
857	              {
858	                printf("[xiaozhi] <<< goodbye\n");
859	                app->ws_connected = false;
860	                cJSON_Delete(root);
861	                free(json);
862	                break;
863	              }
864	            else if (strcmp(tstr, "mcp") == 0)
865	              {
866	                printf("[xiaozhi] <<< MCP message\n");
867	                /* Check if this is tools/list — after responding, the MCP
868	                 * handshake is complete and we should proceed to listen.
869	                 */
870	                cJSON *payload = cJSON_GetObjectItem(root, "payload");
871	                cJSON *method = payload ?
872	                  cJSON_GetObjectItem(payload, "method") : NULL;
873	                bool is_tools_list = cJSON_IsString(method) &&
874	                  strcmp(method->valuestring, "tools/list") == 0;
875	
876	                mcp_server_handle_message(root, mcp_send_json);
877	
878	                if (is_tools_list)
879	                  {
880	                    printf("[xiaozhi] MCP handshake done\n");
881	                    app->mcp_done = true;
882	                  }
883	              }
884	            else if (strcmp(tstr, "hello") == 0)
885	              {
886	                cJSON *sid = cJSON_GetObjectItem(root, "session_id");
887	                if (cJSON_IsString(sid))
888	                  {
889	                    strncpy(app->session_id, sid->valuestring,
890	                            sizeof(app->session_id) - 1);
891	                    app->session_id[sizeof(app->session_id) - 1] = '\0';
892	                    printf("[xiaozhi] <<< hello: session_id=%s\n",
893	                           app->session_id);
894	                  }
895	
896	                /* In the connect phase we only need the hello response to
897	                 * obtain the session_id; bail out so we don't block here
898	                 * waiting for server audio that never comes before we've
899	                 * sent listen:start. The server also times out (~10s) if
900	                 * it doesn't see a listen request soon after hello.
901	                 */
902	                if (stop_on_hello)
903	                  {
904	                    cJSON_Delete(root);
905	                    free(json);
906	                    return;
907	                  }
908	              }
909	            else
910	              {
911	                /* Print full message for debugging unknown types (e.g. error). */
912	                char *out = cJSON_PrintUnformatted(root);
913	                printf("[xiaozhi] <<< %s\n", out ? out : tstr);
914	                if (out)
915	                  {
916	                    free(out);
917	                  }
918	              }
919	
920	            cJSON_Delete(root);
921	          }
922	        else
923	          {
924	            printf("[xiaozhi] <<< (parse err) %.*s\n",
925	                   (int)plen, (const char *)payload);
926	          }
927	
928	        free(json);
929	      }
930	
931	      waited += 60;
932	    }
933	}
