935	/* Dialog thread: runs the full OTA -> dialog flow off the main (UI) thread.
936	 */
937	static void *dialog_thread(void *arg)
938	{
939	  struct xiaozhi_app_s *app = arg;
940	  struct xiaozhi_ota_config_s ota;
941	  const char *mac = XIAOZHI_MAC_DEFAULT;
942	  char client_id[40];
943	  int ret;
944	
945	  snprintf(client_id, sizeof(client_id),
946	           "00000000-0000-0000-0000-%08x", 0xa1b2c3d7);
947	
948	  /* Init audio subsystem (creates Opus encoder). */
949	  app->audio = xiaozhi_audio_init();
950	  if (app->audio == NULL)
951	    {
952	      printf("[xiaozhi] audio init failed\n");
953	      app->state = XZ_STATE_ERROR;
954	      return NULL;
955	    }
956	
957	  /* Init MCP tool server and set app context for send callback. */
958	
959	  s_mcp_app = app;
960	  mcp_register_tools();
961	
962	  /* Step 1: OTA. */
963	  app->state = XZ_STATE_OTA;
964	  printf("[xiaozhi] step 1: OTA\n");
965	  ret = xiaozhi_ota_fetch(mac, &ota);
966	  if (ret != 0)
967	    {
968	      printf("[xiaozhi] OTA failed: %d\n", ret);
969	      app->state = XZ_STATE_ERROR;
970	      return NULL;
971	    }
972	
973	  /* Step 2: wss connect (TLS + ws upgrade). */
974	  app->state = XZ_STATE_CONNECT;
975	  printf("[xiaozhi] step 2: wss connect\n");
976	  ret = xiaozhi_ws_connect(&app->ws, ota.ws_url, ota.ws_token, mac,
977	                           client_id);
978	  if (ret != 0)
979	    {
980	      printf("[xiaozhi] ws connect failed: %d\n", ret);
981	      app->state = XZ_STATE_ERROR;
982	      return NULL;
983	    }
984	
985	  app->ws_connected = true;
986	
987	  /* Step 3: send the hello handshake, then wait for the server's hello
988	   * response which carries the session_id. The server times out (~10s)
989	   * if it never receives a hello, so we must send ours first.
990	   */
991	  printf("[xiaozhi] step 3: send hello + wait hello response\n");
992	  {
993	    cJSON *hello = cJSON_CreateObject();
994	    cJSON_AddStringToObject(hello, "type", "hello");
995	    cJSON_AddNumberToObject(hello, "version", 3);
996	    cJSON_AddStringToObject(hello, "transport", "websocket");
997	
998	    cJSON *ap = cJSON_CreateObject();
999	    cJSON_AddStringToObject(ap, "format", "opus");
1000	    cJSON_AddNumberToObject(ap, "sample_rate", 16000);
1001	    cJSON_AddNumberToObject(ap, "channels", 1);
1002	    cJSON_AddNumberToObject(ap, "frame_duration", 60);
1003	    cJSON_AddItemToObject(hello, "audio_params", ap);
1004	
1005	    /* Advertise MCP tool support to the server. */
1006	
1007	    mcp_server_add_hello_features(hello);
1008	
1009	    char *hello_str = cJSON_PrintUnformatted(hello);
1010	    printf("[xiaozhi] >>> hello json: %s\n", hello_str ? hello_str : "null");
1011	    if (hello_str)
1012	      {
1013	        free(hello_str);
1014	      }
1015	    ret = send_json(app, hello);
1016	    cJSON_Delete(hello);
1017	    if (ret != 0)
1018	      {
1019	        printf("[xiaozhi] hello send failed: %d\n", ret);
1020	        pthread_mutex_lock(&s_ui_mutex);
1021	        app->state = XZ_STATE_ERROR;
1022	        pthread_mutex_unlock(&s_ui_mutex);
1023	        goto out;
1024	      }
1025	  }
1026	
1027	  /* Receive the server hello response to get session_id. stop_on_hello
1028	   * returns immediately once we have it, so we don't block waiting for
1029	   * audio the server won't send before listen:start.
1030	   */
1031	  recv_loop(app, 5000, true);
1032	  if (app->session_id[0] == '\0')
1033	    {
1034	      printf("[xiaozhi] no session_id, abort\n");
1035	      pthread_mutex_lock(&s_ui_mutex);
1036	      app->state = XZ_STATE_ERROR;
1037	      pthread_mutex_unlock(&s_ui_mutex);
1038	      goto out;
1039	    }
1040	
1041	  /* Step 3b: Process MCP initialize from server.
1042	   * The server may send MCP initialize after hello but before we start
1043	   * listening. We need to handle it so the server knows our tools.
1044	   * The loop breaks early once tools/list is handled (mcp_done flag).
1045	   */
1046	
1047	  printf("[xiaozhi] step 3b: wait for MCP initialize\n");
1048	  app->mcp_done = false;
1049	  recv_loop(app, 3000, false);
1050	
1051	  /* Check if connection survived the MCP exchange.
1052	   * The TLS read may fail during recv_loop (error -0x5), killing
1053	   * the connection. If so, abort instead of continuing with a dead
1054	   * connection which would cause the dialog to loop forever.
1055	   */
1056	  if (!app->ws_connected)
1057	    {
1058	      printf("[xiaozhi] connection lost during MCP exchange, abort\n");
1059	      goto out;
1060	    }
1061	
1062	  /* Step 4: listen start + capture + listen stop. */
1063	  pthread_mutex_lock(&s_ui_mutex);
1064	  app->state = XZ_STATE_LISTENING;
1065	  pthread_mutex_unlock(&s_ui_mutex);
1066	  printf("[xiaozhi] step 4: listen start + capture, session_id=%s\n",
1067	         app->session_id);
1068	  {
1069	    cJSON *listen = cJSON_CreateObject();
1070	    cJSON_AddStringToObject(listen, "session_id", app->session_id);
1071	    cJSON_AddStringToObject(listen, "type", "listen");
1072	    cJSON_AddStringToObject(listen, "state", "start");
1073	    cJSON_AddStringToObject(listen, "mode", "manual");
1074	    char *json_str = cJSON_PrintUnformatted(listen);
1075	    printf("[xiaozhi] >>> listen start json: %s\n", json_str ? json_str : "null");
1076	    if (json_str)
1077	      {
1078	        free(json_str);
1079	      }
1080	    send_json(app, listen);
1081	    cJSON_Delete(listen);
1082	  }
1083	
1084	  ret = xiaozhi_audio_start_capture(app->audio);
1085	  if (ret != 0)
1086	    {
1087	      printf("[xiaozhi] capture start failed: %d\n", ret);
1088	      pthread_mutex_lock(&s_ui_mutex);
1089	      app->state = XZ_STATE_ERROR;
1090	      pthread_mutex_unlock(&s_ui_mutex);
1091	      goto out;
1092	    }
1093	
1094	  {
1095	    struct uplink_ctx_s uc;
1096	    uc.app = app;
1097	    uc.seconds = XZ_DIALOG_SECONDS;
1098	    uplink_worker(&uc);
1099	  }

1100	
1101	  xiaozhi_audio_stop_capture(app->audio);
1102	
1103	  /* listen stop. */
1104	  {
1105	    cJSON *stop = cJSON_CreateObject();
1106	    cJSON_AddStringToObject(stop, "session_id", app->session_id);
1107	    cJSON_AddStringToObject(stop, "type", "listen");
1108	    cJSON_AddStringToObject(stop, "state", "stop");
1109	    char *json_str = cJSON_PrintUnformatted(stop);
1110	    printf("[xiaozhi] >>> listen stop json: %s\n", json_str ? json_str : "null");
1111	    if (json_str)
1112	      {
1113	        free(json_str);
1114	      }
1115	    send_json(app, stop);
1116	    cJSON_Delete(stop);
1117	  }
1118	
1119	  /* Step 5: receive stt + tts + playback (up to 20s). */
1120	  app->state = XZ_STATE_THINKING;
1121	  printf("[xiaozhi] step 5: wait stt/tts (20s)\n");
1122	  app->mcp_done = false;  /* Reset so recv_loop doesn't exit early. */
1123	  recv_loop(app, 20000, false);
1124	
1125	out:
1126	  if (app->tts_playing)
1127	    {
1128	      xiaozhi_audio_stop_playback(app->audio);
1129	    }
1130	
1131	  xiaozhi_audio_deinit(app->audio);
1132	  xiaozhi_ws_close(&app->ws);
1133	
1134	  pthread_mutex_lock(&s_ui_mutex);
1135	  app->state = XZ_STATE_DONE;
1136	  pthread_mutex_unlock(&s_ui_mutex);
1137	  printf("[xiaozhi] === done: stt=%s tts=%d ===\n",
1138	         app->got_stt ? "yes" : "no", app->tts_sentences);
1139	
1140	  /* Reset state so user can start a new conversation. */
1141	  app->dialog_started = false;
1142	  app->ws_connected = false;
1143	  app->mcp_done = false;
1144	  app->got_stt = false;
1145	  app->tts_playing = false;
1146	  app->tts_sentences = 0;
1147	  memset(app->session_id, 0, sizeof(app->session_id));
1148	  memset(app->stt_text, 0, sizeof(app->stt_text));
1149	  memset(app->tts_text, 0, sizeof(app->tts_text));
1150	
1151	  /* Set flag to show start button - LVGL timer will handle the actual LVGL operation.
1152	   * Do NOT call lv_obj_clear_flag directly from this thread! */
1153	  app->show_start_btn = true;
1154	
1155	  return NULL;
1156	}
