1158	/* Start button click handler: kicks off the dialog thread on demand.
1159	 * The user taps this after WiFi is up, so OTA can reach the server.
1160	 */
1161	static void start_btn_event_cb(lv_event_t *e)
1162	{
1163	  struct xiaozhi_app_s *app = &g_app;
1164	  LV_UNUSED(e);
1165	
1166	  if (app->dialog_started)
1167	    {
1168	      return;   /* already running */
1169	    }
1170	
1171	  pthread_mutex_lock(&s_ui_mutex);
1172	  app->dialog_started = true;
1173	  app->state = XZ_STATE_OTA;
1174	  pthread_mutex_unlock(&s_ui_mutex);
1175	
1176	  /* Hide the start button once the dialog is launched. */
1177	  if (app->start_btn != NULL)
1178	    {
1179	      lv_obj_add_flag(app->start_btn, LV_OBJ_FLAG_HIDDEN);
1180	    }
1181	
1182	  pthread_attr_t attr;
1183	  pthread_attr_init(&attr);
1184	  pthread_attr_setstacksize(&attr, 65536);
1185	
1186	  int ret = pthread_create(NULL, &attr, dialog_thread, app);
1187	  pthread_attr_destroy(&attr);
1188	
1189	  if (ret != 0)
1190	    {
1191	      printf("[xiaozhi] dialog thread create failed: %d\n", ret);
1192	      pthread_mutex_lock(&s_ui_mutex);
1193	      app->state = XZ_STATE_ERROR;
1194	      app->dialog_started = false;
1195	      pthread_mutex_unlock(&s_ui_mutex);
1196	      if (app->start_btn != NULL)
1197	        {
1198	          lv_obj_clear_flag(app->start_btn, LV_OBJ_FLAG_HIDDEN);
1199	        }
1200	    }
1201	}
