160	ssize_t xiaozhi_audio_read_opus(struct xiaozhi_audio_s *a,
161	                                uint8_t *buf, size_t maxlen)
162	{
163	  ssize_t total = 0;
164	  ssize_t n;
165	  int encoded_bytes;
166	  int frame_samples;
167	
168	  if (a == NULL || a->recorder == NULL || buf == NULL)
169	    {
170	      return -EINVAL;
171	    }
172	
173	  /* Read exactly one 60ms PCM frame from the SMF recorder.
174	   * At 16kHz mono 16-bit, one 60ms frame = 960 samples = 1920 bytes.
175	   * media_recorder_read_data may return partial reads, so loop until
176	   * we have the full frame.
177	   */
178	  while (total < XZ_PCM_BUF_SIZE)
179	    {
180	      n = media_recorder_read_data(a->recorder,
181	                                   (uint8_t *)a->pcm_buf + total,
182	                                   XZ_PCM_BUF_SIZE - total);
183	      if (n <= 0)
184	        {
185	          printf("[xiaozhi] pcm read returned: %zd (got %zd/%d)\n",
186	                 n, total, XZ_PCM_BUF_SIZE);
187	          return n > 0 ? -EIO : n;
188	        }
189

190	      total += n;
191	    }
192	
193	  /* Encode PCM to Opus. opus_encode takes sample count, not byte count.
194	   * frame_samples = total_bytes / (channels * bytes_per_sample)
195	   *               = 1920 / (1 * 2) = 960 samples for 60ms at 16kHz.
196	   */
197	  frame_samples = total / (XZ_OPUS_CHANNELS * sizeof(opus_int16));
198	  encoded_bytes = opus_encode(a->opus_encoder,
199	                              a->pcm_buf,
200	                              frame_samples,
201	                              a->opus_buf,
202	                              XZ_OPUS_FRAME_MAX);
203	  if (encoded_bytes < 0)
204	    {
205	      printf("[xiaozhi] opus_encode error: %s (samples=%d)\n",
206	             opus_strerror(encoded_bytes), frame_samples);
207	      return -EIO;
208	    }
209	
210	  /* Copy encoded frame to caller's buffer. */
211	  if ((size_t)encoded_bytes > maxlen)
212	    {
213	      printf("[xiaozhi] opus frame too large: %d > %zu\n", encoded_bytes, maxlen);
214	      return -ENOMEM;
215	    }
216	
217	  memcpy(buf, a->opus_buf, encoded_bytes);
218	
219	  return (ssize_t)encoded_bytes;

220	}
