161	ssize_t xiaozhi_audio_read_opus(struct xiaozhi_audio_s *a,
162	                                uint8_t *buf, size_t maxlen)
163	{
164	  ssize_t total = 0;
165	  ssize_t n;
166	  int encoded_bytes;
167	  int frame_samples;
168	
169	  if (a == NULL || a->recorder == NULL || buf == NULL)
170	    {
171	      return -EINVAL;
172	    }
173	
174	  /* Read exactly one 60ms PCM frame from the SMF recorder.
175	   * At 24kHz mono 16-bit, one 60ms frame = 1440 samples = 2880 bytes.
176	   * media_recorder_read_data may return partial reads, so loop until
177	   * we have the full frame.
178	   */
179	  while (total < XZ_PCM_BUF_SIZE)
180	    {
181	      n = media_recorder_read_data(a->recorder,
182	                                   (uint8_t *)a->pcm_buf + total,
183	                                   XZ_PCM_BUF_SIZE - total);
184	      if (n <= 0)
185	        {
186	          printf("[xiaozhi] pcm read returned: %zd (got %zd/%d)\n",
187	                 n, total, XZ_PCM_BUF_SIZE);
188	          return n > 0 ? -EIO : n;
189	        }
190	
191	      total += n;
192	    }
193	
194	  /* Encode PCM to Opus. opus_encode takes sample count, not byte count.
195	   * frame_samples = total_bytes / (channels * bytes_per_sample)
196	   *               = 2880 / (1 * 2) = 1440 samples for 60ms at 24kHz.
197	   */
198	  frame_samples = total / (XZ_OPUS_CHANNELS * sizeof(opus_int16));
199	  encoded_bytes = opus_encode(a->opus_encoder,
200	                              a->pcm_buf,
201	                              frame_samples,
202	                              a->opus_buf,
203	                              XZ_OPUS_FRAME_MAX);
204	  if (encoded_bytes < 0)
205	    {
206	      printf("[xiaozhi] opus_encode error: %s (samples=%d)\n",
207	             opus_strerror(encoded_bytes), frame_samples);
208	      return -EIO;
209	    }
210	
211	  /* Copy encoded frame to caller's buffer. */
212	  if ((size_t)encoded_bytes > maxlen)
213	    {
214	      printf("[xiaozhi] opus frame too large: %d > %zu\n", encoded_bytes, maxlen);
215	      return -ENOMEM;
216	    }
217	
218	  memcpy(buf, a->opus_buf, encoded_bytes);
219	
220	  return (ssize_t)encoded_bytes;
221	}
