/* Simple linear-interpolation resampler: 16kHz -> 24kHz mono 16-bit PCM.
 * in_samples = 960 (60ms at 16kHz), out_samples = 1440 (60ms at 24kHz). */
static void resample_16k_to_24k(const opus_int16 *in, opus_int16 *out,
                                int in_samples, int out_samples)
{
  int i;
  for (i = 0; i < out_samples; i++)
    {
      /* Map output index back to input fractional index. */
      long pos = (long)i * in_samples / out_samples;
      int idx = (int)pos;
