ssize_t xiaozhi_audio_read_opus(struct xiaozhi_audio_s *a,
                                uint8_t *buf, size_t maxlen)
{
  ssize_t total = 0;
  ssize_t n;
  int encoded_bytes;
  int frame_samples;
  opus_int16 *resampled;

  if (a == NULL || a->recorder == NULL || buf == NULL)
    {
      return -EINVAL;
    }

  /* Read exactly one 60ms PCM frame from the SMF recorder.
   * At 16kHz mono 16-bit, one 60ms frame = 960 samples = 1920 bytes.
   * media_recorder_read_data may return partial reads, so loop until
   * we have the full frame.
   */
  while (total < XZ_PCM_MIC_SIZE)
    {
      n = media_recorder_read_data(a->recorder,
                                   (uint8_t *)a->pcm_buf + total,
                                   XZ_PCM_MIC_SIZE - total);
      if (n <= 0)
        {
          printf("[xiaozhi] pcm read returned: %zd (got %zd/%d)\n",
                 n, total, XZ_PCM_MIC_SIZE);
          return n > 0 ? -EIO : n;
        }

      total += n;
    }

  /* Resample 16kHz -> 24kHz before encoding.
   * mic captures at 16kHz, server expects 24kHz opus. */
  resampled = (opus_int16 *)(a->opus_buf + XZ_OPUS_FRAME_MAX);
  frame_samples = total / (XZ_OPUS_CHANNELS * sizeof(opus_int16));  /* 960 */
  resample_16k_to_24k(a->pcm_buf, resampled, frame_samples,
                      XZ_OPUS_FRAME_SIZE);  /* 960 -> 1440 */

  /* Encode resampled PCM to Opus at 24kHz. */
  encoded_bytes = opus_encode(a->opus_encoder,
                              resampled,
                              XZ_OPUS_FRAME_SIZE,  /* 1440 samples */
                              a->opus_buf,
                              XZ_OPUS_FRAME_MAX);
  if (encoded_bytes < 0)
    {
      printf("[xiaozhi] opus_encode error: %s (samples=%d)\n",
             opus_strerror(encoded_bytes), XZ_OPUS_FRAME_SIZE);
      return -EIO;
    }

  /* Copy encoded frame to caller's buffer. */
  if ((size_t)encoded_bytes > maxlen)
    {
      printf("[xiaozhi] opus frame too large: %d > %zu\n", encoded_bytes, maxlen);
      return -ENOMEM;
    }

  memcpy(buf, a->opus_buf, encoded_bytes);

  return (ssize_t)encoded_bytes;
}

