/* Windowed-sinc resampler: 16kHz -> 24kHz mono 16-bit PCM.
 * Uses a 64-tap Kaiser-windowed sinc filter for high quality.
 * Ratio = 24/16 = 3/2, so we upsample by 3 then downsample by 2. */
#define SINC_TAPS  64
#define SINC_WIDTH 3   /* number of zero-crossings per side */
#define OVERSAMPLE 3   /* upsample factor */
#define DOWNFACTOR 2   /* downsample factor */

static int16_t sinc_lut[OVERSAMPLE][SINC_TAPS];  /* precomputed filter taps */
static int sinc_inited;

static void sinc_init(void)
{
  int phase, tap;
  for (phase = 0; phase < OVERSAMPLE; phase++)
    {
      int32_t sum = 0;
      for (tap = 0; tap < SINC_TAPS; tap++)
        {
          /* Center the sinc at the phase position. */
          double x = (double)(tap - SINC_TAPS / 2 + phase) / OVERSAMPLE;
          /* Windowed sinc: sinc(x) * Kaiser(beta=5). */
          double sinc_val = (x == 0.0) ? 1.0 : sin(3.14159265 * x) / (3.14159265 * x);
          /* Kaiser window approximation (beta=5). */
          double arg = 5.0 * sqrt(1.0 - ((double)(tap - SINC_TAPS/2) / (SINC_TAPS/2)) *
                                  ((double)(tap - SINC_TAPS/2) / (SINC_TAPS/2)));
          double kaiser = 1.0;  /* simplified: use rectangular for now */
          if (arg < 5.0 && arg > -5.0)
            {
              /* Bessel I0 approximation for Kaiser window */
              double t = arg;
              kaiser = 1.0 + t*t/4.0 + t*t*t*t/64.0 + t*t*t*t*t*t/2304.0;
            }
          int32_t tap_val = (int32_t)(sinc_val * kaiser * 32768.0 / OVERSAMPLE);
          sinc_lut[phase][tap] = (int16_t)tap_val;
          sum += tap_val;
        }
    }
  sinc_inited = 1;
}

static void resample_16k_to_24k(const opus_int16 *in, opus_int16 *out,
                                int in_samples, int out_samples)
{
  int i, tap;
  int32_t ratio_num = OVERSAMPLE;   /* upsample factor */
  int32_t ratio_den = DOWNFACTOR;   /* downsample factor */

  if (!sinc_inited)
    {
      sinc_init();
    }

  for (i = 0; i < out_samples; i++)
    {
      /* Map output index to input position: pos = i * in_samples / out_samples */
      int64_t pos64 = (int64_t)i * in_samples * OVERSAMPLE / out_samples;
      int int_pos = (int)(pos64 / OVERSAMPLE);  /* integer sample index */
      int phase = (int)(pos64 % OVERSAMPLE);     /* fractional phase 0..OVERSAMPLE-1 */

      int32_t acc = 0;
      for (tap = 0; tap < SINC_TAPS; tap++)
        {
          int idx = int_pos - SINC_TAPS / 2 + tap;
          /* Clamp to valid range */
          if (idx < 0) idx = 0;
          if (idx >= in_samples) idx = in_samples - 1;
          acc += (int32_t)in[idx] * sinc_lut[phase][tap];
        }

      /* Scale down: filter taps were scaled by OVERSAMPLE, so divide back. */
      acc = (acc + 16384) >> 15;  /* round and scale */
      if (acc > 32767) acc = 32767;
      if (acc < -32768) acc = -32768;
      out[i] = (int16_t)acc;
    }
