      int64_t pos64 = (int64_t)i * in_samples * OVERSAMPLE / out_samples;
      int int_pos = (int)(pos64 / OVERSAMPLE);  /* integer sample index */
      int phase = (int)(pos64 % OVERSAMPLE);     /* fractional phase 0..OVERSAMPLE-1 */

      int32_t acc = 0;
      for (tap = 0; tap < SINC_TAPS; tap++)
        {
          int idx = int_pos - SINC_TAPS / 2 + tap;
          /* Clamp to valid range */
          if (idx < 0) idx = 0;
          if (idx >= in_samples) idx = in_samples - 1;
          acc += (int32_t)in[idx] * sinc_lut[phase][tap];
        }

      /* Scale down: filter taps were scaled by OVERSAMPLE, so divide back. */
      acc = (acc + 16384) >> 15;  /* round and scale */
      if (acc > 32767) acc = 32767;
      if (acc < -32768) acc = -32768;
      out[i] = (int16_t)acc;
    }
}

