/* 4-point cubic interpolation resampler: 16kHz -> 24kHz mono 16-bit PCM.
 * Uses Catmull-Rom spline for smooth interpolation without math library.
 * Quality is much better than linear interpolation for speech. */
static void resample_16k_to_24k(const opus_int16 *in, opus_int16 *out,
                                int in_samples, int out_samples)
{
  int i;
  for (i = 0; i < out_samples; i++)
    {
      /* Map output index to input fractional position. */
      int64_t pos = (int64_t)i * in_samples * 1000 / out_samples;
      int idx = (int)(pos / 1000);      /* integer part */
      int frac = (int)(pos % 1000);     /* fractional part 0..999 */

      /* Get 4 surrounding samples (Catmull-Rom uses p[0]..p[3]). */
      int i0 = idx - 1;
      int i1 = idx;
      int i2 = idx + 1;
      int i3 = idx + 2;

      /* Clamp indices */
      if (i0 < 0) i0 = 0;
      if (i2 >= in_samples) i2 = in_samples - 1;
      if (i3 >= in_samples) i3 = in_samples - 1;

      int32_t p0 = in[i0];
      int32_t p1 = in[i1];
      int32_t p2 = in[i2];
      int32_t p3 = in[i3];

      /* Catmull-Rom cubic interpolation:
       * t = frac/1000, result = 0.5*((2*p1) + (-p0+p2)*t + (2*p0-5*p1+4*p2-p3)*t^2 + (-p0+3*p1-3*p2+p3)*t^3)
       * Using fixed-point math with 1/1000 precision. */
      int32_t t = frac;          /* 0..999 */
      int32_t t2 = t * t / 1000;   /* t^2 scaled */
      int32_t t3 = t2 * t / 1000;  /* t^3 scaled */

      int32_t a = -p0 + 3*p1 - 3*p2 + p3;
      int32_t b = 2*p0 - 5*p1 + 4*p2 - p3;
      int32_t c = -p0 + p2;
      int32_t d = 2*p1;

      int32_t result = (d*1000 + c*t + b*t2 + a*t3 + 500) / 1000;
      result = (result + 1) / 2;  /* multiply by 0.5 */

      if (result > 32767) result = 32767;
      if (result < -32768) result = -32768;
      out[i] = (int16_t)result;
    }
}

