/* Audio frontend: DC removal + noise gate + soft limiter.
 * Processes 16kHz mono PCM in-place before resampling.
 * Improves SNR for STT by removing DC offset and suppressing noise. */
static void audio_frontend_process(struct xiaozhi_audio_s *a,
                                   opus_int16 *buf, int samples)
{
  int i;
  int voice_detected = 0;

  for (i = 0; i < samples; i++)
    {
      int32_t s = buf[i];

      /* 1. DC offset removal (single-pole HPF, cutoff ~100Hz at 16kHz).
       *    alpha = 328/32768 ≈ 0.01, fc = alpha*fs/(2*pi) ≈ 102Hz */
      a->dc_avg += ((s << 15) - a->dc_avg) >> 15;
      s = s - (a->dc_avg >> 15);

      /* Clamp after DC removal */
      if (s > 32767) s = 32767;
      if (s < -32768) s = -32768;
      buf[i] = (opus_int16)s;
    }

  /* 2. Noise gate: suppress frames below threshold.
   *    Check if any sample exceeds the gate threshold. */
  for (i = 0; i < samples; i++)
    {
      int16_t abs_s = buf[i];
      if (abs_s < 0) abs_s = -abs_s;
      if (abs_s > AF_GATE_THRESH)
        {
          voice_detected = 1;
          break;
        }
    }

  if (voice_detected)
    {
      a->gate_hold = AF_GATE_HOLD;
    }
  else if (a->gate_hold > 0)
    {
      a->gate_hold--;
      voice_detected = 1;  /* Keep passing audio during hold */
    }

  if (!voice_detected)
    {
      /* Silence: zero out the buffer */
      memset(buf, 0, samples * sizeof(opus_int16));
    }

  /* 3. Soft limiter: prevent clipping before opus encoder. */
  for (i = 0; i < samples; i++)
    {
      int32_t s = buf[i];
      if (s > AF_LIMIT_THRESH)
        {
          s = AF_LIMIT_THRESH + ((s - AF_LIMIT_THRESH) >> 2);
          if (s > 32767) s = 32767;
        }
      else if (s < -AF_LIMIT_THRESH)
        {
          s = -AF_LIMIT_THRESH + ((s + AF_LIMIT_THRESH) >> 2);
          if (s < -32768) s = -32768;
        }
      buf[i] = (opus_int16)s;
    }
}

