176	/* Audio frontend: DC removal + noise gate + soft limiter.
177	 * Processes 16kHz mono PCM in-place before resampling.
178	 * Improves SNR for STT by removing DC offset and suppressing noise. */
179	static void audio_frontend_process(struct xiaozhi_audio_s *a,
180	                                   opus_int16 *buf, int samples)
181	{
182	  int i;
183	  int voice_detected = 0;
184	
185	  for (i = 0; i < samples; i++)
186	    {
187	      int32_t s = buf[i];
188	
189	      /* 1. DC offset removal (single-pole HPF, cutoff ~100Hz at 16kHz).
190	       *    alpha = 328/32768 ≈ 0.01, fc = alpha*fs/(2*pi) ≈ 102Hz */
191	      a->dc_avg += ((s << 15) - a->dc_avg) >> 15;
192	      s = s - (a->dc_avg >> 15);
193	
194	      /* Clamp after DC removal */
195	      if (s > 32767) s = 32767;
196	      if (s < -32768) s = -32768;
197	      buf[i] = (opus_int16)s;
198	    }
199	
200	  /* 2. Noise gate: suppress frames below threshold.
201	   *    Check if any sample exceeds the gate threshold. */
202	  for (i = 0; i < samples; i++)
203	    {
204	      int16_t abs_s = buf[i];
205	      if (abs_s < 0) abs_s = -abs_s;
206	      if (abs_s > AF_GATE_THRESH)
207	        {
208	          voice_detected = 1;
209	          break;
210	        }
211	    }
212	
213	  if (voice_detected)
214	    {
215	      a->gate_hold = AF_GATE_HOLD;
216	    }
217	  else if (a->gate_hold > 0)
218	    {
219	      a->gate_hold--;
220	      voice_detected = 1;  /* Keep passing audio during hold */
221	    }
222	
223	  if (!voice_detected)
224	    {
225	      /* Silence: zero out the buffer */
226	      memset(buf, 0, samples * sizeof(opus_int16));
227	    }
228	
229	  /* 3. Soft limiter: prevent clipping before opus encoder. */
230	  for (i = 0; i < samples; i++)
231	    {
232	      int32_t s = buf[i];
233	      if (s > AF_LIMIT_THRESH)
234	        {
235	          s = AF_LIMIT_THRESH + ((s - AF_LIMIT_THRESH) >> 2);
236	          if (s > 32767) s = 32767;
237	        }
238	      else if (s < -AF_LIMIT_THRESH)
239	        {

239	        {
240	          s = -AF_LIMIT_THRESH + ((s + AF_LIMIT_THRESH) >> 2);
241	          if (s < -32768) s = -32768;
242	        }
243	      buf[i] = (opus_int16)s;
244	    }
245	}
