247	/* 4-point cubic interpolation resampler: 16kHz -> 24kHz mono 16-bit PCM.
248	 * Uses Catmull-Rom spline for smooth interpolation without math library.
249	 * Quality is much better than linear interpolation for speech. */
250	static void resample_16k_to_24k(const opus_int16 *in, opus_int16 *out,
251	                                int in_samples, int out_samples)
252	{
253	  int i;
254	  for (i = 0; i < out_samples; i++)
255	    {
256	      /* Map output index to input fractional position. */
257	      int64_t pos = (int64_t)i * in_samples * 1000 / out_samples;
258	      int idx = (int)(pos / 1000);      /* integer part */
259	      int frac = (int)(pos % 1000);     /* fractional part 0..999 */
260	
261	      /* Get 4 surrounding samples (Catmull-Rom uses p[0]..p[3]). */
262	      int i0 = idx - 1;
263	      int i1 = idx;
264	      int i2 = idx + 1;
265	      int i3 = idx + 2;
266	
267	      /* Clamp indices */
268	      if (i0 < 0) i0 = 0;
269	      if (i2 >= in_samples) i2 = in_samples - 1;
270	      if (i3 >= in_samples) i3 = in_samples - 1;
271	
272	      int32_t p0 = in[i0];
273	      int32_t p1 = in[i1];
274	      int32_t p2 = in[i2];
275	      int32_t p3 = in[i3];
276	
277	      /* Catmull-Rom cubic interpolation:
278	       * t = frac/1000 (in [0,1)), result = 0.5*(2*p1 + (-p0+p2)*t + (2*p0-5*p1+4*p2-p3)*t^2 + (-p0+3*p1-3*p2+p3)*t^3)
279	       * Using fixed-point with SCALE=1000. t is already frac (0..999). */
280	      int32_t t = frac;           /* 0..999, represents t*SCALE */
281	      int32_t t2 = t * t / 1000; /* t^2 * SCALE */
282	      int32_t t3 = t2 * t / 1000; /* t^3 * SCALE */
283	
284	      int32_t a = -p0 + 3*p1 - 3*p2 + p3;
285	      int32_t b = 2*p0 - 5*p1 + 4*p2 - p3;
286	      int32_t c = -p0 + p2;
287	      int32_t d = 2*p1;
288	
289	      /* All terms are in fixed-point SCALE. d is already scaled by SCALE implicitly. */
290	      int32_t result = (d * 1000 + c * t + b * t2 + a * t3 + 500) / 2000;
291	
292	      if (result > 32767) result = 32767;
293	      if (result < -32768) result = -32768;
294	      out[i] = (int16_t)result;
295	    }
296	}
