298	ssize_t xiaozhi_audio_read_opus(struct xiaozhi_audio_s *a,
299	                                uint8_t *buf, size_t maxlen)
300	{
301	  ssize_t total = 0;
302	  ssize_t n;
303	  int encoded_bytes;
304	  int frame_samples;
305	  int i;
306	  int32_t mic_energy = 0;
307	  int16_t mic_max = 0;
308	
309	  if (a == NULL || a->recorder == NULL || buf == NULL)
310	    {
311	      return -EINVAL;
312	    }
313	
314	  /* Read exactly one 60ms PCM frame from the SMF recorder.
315	   * At 16kHz mono 16-bit, one 60ms frame = 960 samples = 1920 bytes.
316	   * media_recorder_read_data may return partial reads, so loop until
317	   * we have the full frame.
318	   */
319	  while (total < XZ_PCM_MIC_SIZE)
320	    {
321	      n = media_recorder_read_data(a->recorder,
322	                                   (uint8_t *)a->pcm_buf + total,
323	                                   XZ_PCM_MIC_SIZE - total);
324	      if (n <= 0)
325	        {
326	          printf("[xiaozhi] pcm read returned: %zd (got %zd/%d)\n",
327	                 n, total, XZ_PCM_MIC_SIZE);
328	          return n > 0 ? -EIO : n;
329	        }
330	
331	      total += n;
332	    }
333	
334	  /* Apply audio frontend: DC removal + noise gate + soft limiter. */
335	  frame_samples = total / (XZ_OPUS_CHANNELS * sizeof(opus_int16));  /* 960 */
336	  audio_frontend_process(a, a->pcm_buf, frame_samples);
337	
338	  /* Diagnose mic audio level (first frame only, then every 50th). */
339	  a->frame_count++;
340	  if (a->frame_count <= 1 || (a->frame_count % 50) == 0)
341	    {
342	      for (i = 0; i < frame_samples; i++)
343	        {
344	          int16_t s = a->pcm_buf[i];
345	          mic_energy += (int32_t)s * s;
346	          if (s < 0) s = -s;
347	          if (s > mic_max) mic_max = s;
348	        }
349	      mic_energy /= frame_samples;
350	      printf("[xiaozhi] mic diag: frame=%d samples=%d max=%d rms=%ld\n",
351	             a->frame_count, frame_samples, mic_max, (long)mic_energy);
352	    }
353	
354	  /* Resample 16kHz -> 24kHz before encoding.
355	   * mic captures at 16kHz, server expects 24kHz opus. */
356	  resample_16k_to_24k(a->pcm_buf, a->resample_buf, frame_samples,
357	                      XZ_OPUS_FRAME_SIZE);  /* 960 -> 1440 */
358

358	
359	  /* Encode resampled PCM to Opus at 24kHz. */
360	  encoded_bytes = opus_encode(a->opus_encoder,
361	                              a->resample_buf,
362	                              XZ_OPUS_FRAME_SIZE,  /* 1440 samples */
363	                              a->opus_buf,
364	                              XZ_OPUS_FRAME_MAX);
365	  if (encoded_bytes < 0)
366	    {
367	      printf("[xiaozhi] opus_encode error: %s (samples=%d)\n",
368	             opus_strerror(encoded_bytes), XZ_OPUS_FRAME_SIZE);
369	      return -EIO;
370	    }
371	
372	  /* Copy encoded frame to caller's buffer. */
373	  if ((size_t)encoded_bytes > maxlen)
374	    {
375	      printf("[xiaozhi] opus frame too large: %d > %zu\n", encoded_bytes, maxlen);
376	      return -ENOMEM;
377	    }
378	
379	  memcpy(buf, a->opus_buf, encoded_bytes);
380	
381	  return (ssize_t)encoded_bytes;
382	}
