#define XZ_PLAYER_OPTIONS \
  "oMediaScript=[codec=opus,rate=#24000,ch=#1,bits=#16]"

struct xiaozhi_audio_s
{
  /* Recording path (mic -> audio frontend -> resample -> Opus encode -> send). */
  void             *recorder;       /* SMF recorder handle (void*). */
  OpusEncoder      *opus_encoder;   /* Direct Opus encoder. */
  opus_int16        pcm_buf[XZ_PCM_MIC_SIZE / sizeof(opus_int16)];  /* 16kHz mic input */
  opus_int16        resample_buf[XZ_OPUS_FRAME_SIZE];               /* 24kHz resampled output */
  uint8_t           opus_buf[XZ_OPUS_FRAME_MAX];
  pthread_mutex_t   enc_mutex;
  int               frame_count;    /* Total frames captured (for diag). */
  /* Audio frontend state */
  int32_t           dc_avg;         /* DC offset running average */
  int               gate_hold;      /* Noise gate hold counter */

  /* Playback path (recv Opus -> SMF decode -> speaker). */
  void             *player;         /* SMF player handle (void*). */
};

