int xiaozhi_audio_write_opus(struct xiaozhi_audio_s *a,
                             const uint8_t *data, size_t len)
{
  ssize_t ret;
  int decoded_samples;
  int tts_frame_size;

  if (a == NULL || a->player == NULL || data == NULL)
    {
      return -EINVAL;
    }

  if (a->tts_decoder == NULL)
    {
      printf("[xiaozhi] tts_decoder not initialized\n");
      return -EINVAL;
    }

  /* Decode 24kHz opus frame to PCM.
   * TTS frames use the same 60ms frame size as our encoder. */
  tts_frame_size = XZ_TTS_DECODE_RATE * XZ_OPUS_FRAME_MS / 1000;  /* 1440 */
  decoded_samples = opus_decode(a->tts_decoder,
                                data, len,
                                a->decode_buf,
                                tts_frame_size,
                                0);  /* no FEC */
  if (decoded_samples < 0)
    {
      printf("[xiaozhi] opus_decode error: %s (len=%zu)\n",
             opus_strerror(decoded_samples), len);
      return -EIO;
    }

  /* Resample 24kHz -> 48kHz for speaker output. */
  resample_24k_to_48k(a->decode_buf, a->speaker_buf,
                      decoded_samples,
                      XZ_SPEAKER_RATE * XZ_OPUS_FRAME_MS / 1000);  /* 2880 */

  /* Write raw 48kHz PCM to player. */
  ret = media_player_write_data(a->player, a->speaker_buf,
                                XZ_SPEAKER_RATE * XZ_OPUS_FRAME_MS / 1000 * sizeof(opus_int16));
  if (ret < 0)
    {
      printf("[xiaozhi] player write_data failed: %zd\n", ret);
      return ret;
    }

  return 0;
}

