/****************************************************************************
 * 音频前端处理: DC去除 + AGC + 噪声门限
 * 在 PCM 读取后、Opus 编码前调用，原地处理。
 ****************************************************************************/
static void audio_frontend_process(struct xiaozhi_audio_s *a,
                                   opus_int16 *buf, int samples)
{
  int i;
  int voice_detected = 0;

  /* ---- 1. DC 去除 (单极点高通滤波) ----
   * y[n] = y[n-1] + alpha * (x[n] - y[n-1])
   * alpha = 328/32768 ≈ 0.01, fc ≈ 100Hz @ 16kHz
   * 去除麦克风直流偏移，改善后续处理效果 */
  for (i = 0; i < samples; i++)
    {
      int32_t s = buf[i];
      a->dc_avg += ((s << 15) - a->dc_avg) >> 15;
      s = s - (a->dc_avg >> 15);
      if (s > 32767) s = 32767;
      if (s < -32768) s = -32768;
      buf[i] = (opus_int16)s;
    }

  /* ---- 2. AGC 自动增益控制 ----
   * 测量每帧峰值，动态调整增益使峰值接近目标值。
   * 麦克风原始峰值~960，目标~16000，需约16倍增益。
   * 攻击快(右移8位)、衰减慢(右移4位)，避免增益泵浦。 */
  {
    int16_t frame_peak = 0;
    for (i = 0; i < samples; i++)
      {
        int16_t abs_s = buf[i];
        if (abs_s < 0) abs_s = -abs_s;
        if (abs_s > frame_peak) frame_peak = abs_s;
      }

    if (a->agc_gain == 0 && frame_peak > 0)
      {
        /* 首帧初始化增益 */
        a->agc_gain = ((int32_t)AF_AGC_TARGET << 10) / frame_peak;
      }
    else if (frame_peak > 0)
      {
        int32_t desired = ((int32_t)AF_AGC_TARGET << 10) / frame_peak;
        if (desired < a->agc_gain)
          {
            /* 攻击: 快速降低增益 */
            a->agc_gain -= (a->agc_gain - desired) >> AF_AGC_ATTACK;
          }
        else
          {
            /* 衰减: 慢速提升增益 */
            a->agc_gain += (desired - a->agc_gain) >> AF_AGC_DECAY;
          }
      }

    /* 增益范围限制: 1x ~ 32x */
    if (a->agc_gain < 1024)  a->agc_gain = 1024;
    if (a->agc_gain > 32768) a->agc_gain = 32768;

    /* 应用增益 */
    for (i = 0; i < samples; i++)
      {
        int32_t s = ((int32_t)buf[i] * a->agc_gain) >> 10;
        if (s > 32767) s = 32767;
        if (s < -32768) s = -32768;
        buf[i] = (opus_int16)s;
      }
  }

  /* ---- 3. 噪声门限 ----
   * 检测当前帧是否有语音 (任意采样点超过阈值)。
   * 有语音时重置保持计数器；保持期内继续通过音频；
   * 保持期满且无语音时静音处理。
   * 关键: 先检测再静音，确保门限可重新打开。 */
  for (i = 0; i < samples; i++)
    {
      int16_t abs_s = buf[i];
      if (abs_s < 0) abs_s = -abs_s;
      if (abs_s > AF_GATE_THRESH)
        {
          voice_detected = 1;
          break;
        }
    }

  if (voice_detected)
    {
      a->gate_hold = AF_GATE_HOLD;
    }
  else if (a->gate_hold > 0)
    {
      a->gate_hold--;
      voice_detected = 1;  /* 保持期内继续通过 */
    }

  if (!voice_detected)
    {
      memset(buf, 0, samples * sizeof(opus_int16));
    }
}

