314	  /* Encode PCM to Opus. opus_encode takes sample count, not byte count. */
315	  encoded_bytes = opus_encode(a->opus_encoder,
316	                              a->pcm_buf,
317	                              frame_samples,
318	                              a->opus_buf,
319	                              XZ_OPUS_FRAME_MAX);
320	  if (encoded_bytes < 0)
321	    {
322	      printf("[xiaozhi] opus_encode error: %s (samples=%d)\n",
323	             opus_strerror(encoded_bytes), frame_samples);
324	      return -EIO;

160	  ret = media_recorder_start(a->recorder);
161	  if (ret < 0)
162	    {
163	      printf("[xiaozhi] recorder start failed: %d\n", ret);
164	      media_recorder_close(a->recorder);
165	      a->recorder = NULL;
166	      return ret;
167	    }
168	
169	  printf("[xiaozhi] capture started (16k PCM -> 3A frontend -> opus encode)\n");
170	  return 0;
171	}
